// Synced Material UI documentation (SPEC §8.4–8.5): upstream sections and live examples for portal
// component pages, generated by `pnpm docs:sync` into ./generated (see
// repo-docs/documentation-sync.md). Contract used by the component page template:
//   hasMuiDocs(slug)           true when synced content exists for /components/<slug>
//   <MuiDocsSection slug=… />  renders it; the page module is code-split per slug and loaded on
//                              demand, so render it inside <React.Suspense>
//   preloadMuiDocs(slug)       optional: start (and await) the load, e.g. from a route loader, to
//                              render without a Suspense fallback on client-side navigation
import * as React from 'react';

type PageModule = { default: React.ComponentType };

const pages = import.meta.glob<PageModule>('./generated/pages/*.tsx');
const key = (slug: string) => `./generated/pages/${slug}.tsx`;

type Tracked = Promise<PageModule> & { status?: 'fulfilled' | 'rejected'; value?: PageModule };
const loaded = new Map<string, Tracked>();

function load(slug: string): Tracked | undefined {
  const loader = pages[key(slug)];
  if (!loader) return undefined;
  let promise = loaded.get(slug);
  if (!promise) {
    promise = loader() as Tracked;
    // Status fields let `React.use` return synchronously once the module is in (no re-suspend).
    promise.then(
      (value) => Object.assign(promise!, { status: 'fulfilled', value }),
      () => Object.assign(promise!, { status: 'rejected' }),
    );
    loaded.set(slug, promise);
  }
  return promise;
}

export function hasMuiDocs(slug: string): boolean {
  return key(slug) in pages;
}

export function preloadMuiDocs(slug: string): Promise<void> {
  return load(slug)?.then(() => undefined) ?? Promise.resolve();
}

/** Upstream sections and examples for a component page (suspends while its chunk loads). */
export function MuiDocsSection({ slug }: { slug: string }) {
  const promise = load(slug);
  if (!promise) return null;
  // Always call `use` (hooks must not be conditional); React reads `status`/`value` on the
  // tracked promise and returns synchronously once the chunk has loaded.
  const { default: Page } = React.use(promise as Promise<PageModule>);
  return React.createElement(Page);
}
